INSERT INTO remedies (id, name, condition, condition_label, description, instructions, timing, tracking_note, evidence, caution, premium) VALUES
('cool_clothing_heat_rash', 'Cool, Loose Cotton Clothing', 'heat_rash', 'Heat Rash / Prickly Heat', 'Trapped heat and sweat under tight or synthetic fabric is the main trigger for prickly heat, so airflow is the first fix.', 'Switch to loose, breathable cotton clothing, especially in humid weather, and avoid synthetic fabrics on affected areas.', 'Ongoing, especially in hot/humid weather.', 'Note rash spread and itchiness daily for a week.', 'Reducing sweat trapping is the standard first recommendation for prickly heat.', NULL, false),
('cool_showers_heat_rash', 'Cool Showers and Pat Dry', 'heat_rash', 'Heat Rash / Prickly Heat', 'Cooling the skin reduces sweat gland blockage, which is what causes the small itchy bumps.', 'Take a cool (not cold) shower when you feel a flare starting, and pat skin dry rather than rubbing.', 'As needed, especially after sweating.', 'Track flare frequency over 2 weeks.', 'Cooling the skin is a widely recommended measure for heat rash relief.', NULL, true),
('aloe_heat_rash', 'Aloe Vera Gel', 'heat_rash', 'Heat Rash / Prickly Heat', 'Aloe vera has cooling and anti-inflammatory properties that can soothe irritated, rash-covered skin.', 'Apply a thin layer of pure aloe vera gel to affected areas after cooling the skin.', '1-2x daily during flares.', 'Note itchiness and redness before/after.', 'Aloe vera''s anti-inflammatory effects are documented for soothing irritated skin.', NULL, true),
('antibacterial_soap_odor', 'Wash With Antibacterial Soap', 'body_odor', 'Body Odor Changes', 'Body odor comes from bacteria breaking down sweat, so reducing bacterial load at the source helps most directly.', 'Wash underarms and other sweat-prone areas with an antibacterial or tea-tree soap daily.', 'Daily.', 'Note odor intensity daily for a week.', 'Reducing skin bacteria is the primary mechanism behind odor control products.', NULL, false),
('food_triggers_odor', 'Watch Odor-Triggering Foods', 'body_odor', 'Body Odor Changes', 'Foods like garlic, onions, and red meat can be metabolized into compounds excreted through sweat, intensifying odor.', 'Notice if odor is stronger after certain meals and moderate those foods if so.', 'Ongoing.', 'Log meals alongside odor intensity for 2 weeks.', 'Certain foods are well documented to affect body odor through sweat compounds.', NULL, true),
('natural_deodorant_odor', 'Natural Deodorant with Baking Soda or Charcoal', 'body_odor', 'Body Odor Changes', 'These ingredients help neutralize odor-causing bacteria and absorb excess moisture.', 'Apply a natural deodorant containing baking soda or activated charcoal after washing.', 'Daily.', 'Track freshness through the day.', 'Baking soda''s alkalinity is commonly used to neutralize acidic, odor-causing bacterial byproducts.', 'Baking soda-based deodorants can irritate sensitive skin - patch test first.', true),
('rotate_shoes_foot_odor', 'Rotate Shoes and Dry Them Fully', 'foot_odor', 'Foot Odor', 'Bacteria thrive in damp shoes, so giving footwear time to fully dry between wears reduces odor buildup.', 'Alternate between at least two pairs of shoes so each has 24-48 hours to dry out fully.', 'Ongoing.', 'Note odor levels after switching routines for 2 weeks.', 'Moisture control is the standard first recommendation for foot odor.', NULL, false),
('tea_soak_foot_odor', 'Soak Feet in Black Tea', 'foot_odor', 'Foot Odor', 'Tannins in black tea have a mild astringent effect that can reduce sweating and bacteria on the skin.', 'Soak feet in strong black tea (cooled) for 15-20 minutes, 2-3 times weekly.', '2-3x weekly.', 'Track sweating and odor over 3 weeks.', 'Tannic acid''s astringent properties are traditionally used to reduce foot sweating.', NULL, true),
('breathable_socks_foot_odor', 'Breathable Socks and Foot Powder', 'foot_odor', 'Foot Odor', 'Cotton or moisture-wicking socks combined with foot powder help keep feet dry throughout the day.', 'Wear breathable socks daily and apply foot powder to feet and inside shoes.', 'Daily.', 'Note odor and moisture levels.', 'Moisture-wicking materials reduce the damp environment bacteria need to thrive.', NULL, true),
('antiperspirant_palms', 'Antiperspirant on Palms', 'sweaty_palms', 'Sweaty Palms & Hands', 'The same mechanism that reduces underarm sweat can be applied to palms to reduce excess moisture.', 'Apply a clinical-strength antiperspirant to clean, dry palms before bed.', 'Nightly.', 'Track palm dryness over 2 weeks.', 'Antiperspirants work by temporarily blocking sweat ducts, effective on palms too.', 'Can cause mild irritation - reduce frequency if so.', false),
('cornstarch_palms', 'Cornstarch or Talc-Free Powder', 'sweaty_palms', 'Sweaty Palms & Hands', 'Absorbent powders soak up excess moisture throughout the day, keeping hands drier.', 'Dust a small amount of cornstarch or absorbent powder onto palms as needed.', 'As needed.', 'Note dryness through the day.', 'Absorbent powders are a widely used practical measure for sweaty palms.', NULL, true),
('stress_trigger_palms', 'Manage Underlying Stress/Anxiety Triggers', 'sweaty_palms', 'Sweaty Palms & Hands', 'Palm sweating is often stress-driven, so addressing the trigger can reduce frequency.', 'When you notice sweaty palms, pause for a few slow breaths and identify what triggered the stress response.', 'As needed.', 'Log triggers alongside sweating episodes.', 'Stress-induced sweating (emotional sweating) is a well-documented physiological response.', 'If persistent and disrupting daily life, a doctor can discuss further options.', true),
('moisturize_stretch_marks', 'Regular Moisturizing', 'stretch_marks', 'Stretch Marks', 'Well-hydrated skin is more elastic, which may reduce the visibility of stretch marks over time.', 'Massage a rich body butter or oil into affected areas daily, focusing on hips, thighs, or belly.', 'Daily.', 'Photograph monthly to track changes.', 'Skin hydration supports elasticity, though it won''t erase existing marks entirely.', NULL, false),
('massage_stretch_marks', 'Gentle Massage to Boost Circulation', 'stretch_marks', 'Stretch Marks', 'Massage increases blood flow to the area, which may support skin repair processes over time.', 'Massage affected areas in circular motions for a few minutes while applying oil or cream.', 'Daily.', 'Track skin texture over 2-3 months.', 'Improved local circulation is associated with better skin repair.', NULL, true),
('patience_stretch_marks', 'Be Patient - Marks Fade Naturally Over Time', 'stretch_marks', 'Stretch Marks', 'Stretch marks typically lighten from red/purple to silvery-white over 1-2 years regardless of treatment.', 'Focus on overall skin health rather than expecting marks to disappear completely.', 'Ongoing, long-term.', 'Photograph every few months to see the natural fading process.', 'The natural healing timeline of stretch marks is well documented in dermatology.', NULL, true),
('movement_cellulite', 'Stay Active with Regular Movement', 'cellulite_appearance', 'Cellulite Appearance', 'Building muscle tone underneath the skin can improve the smoothness of skin surface appearance.', 'Include regular strength exercises targeting legs and glutes a few times weekly.', '2-3x weekly.', 'Note skin appearance monthly.', 'Muscle tone can improve the visual smoothness of overlying skin.', NULL, false),
('dry_brush_cellulite', 'Dry Brushing', 'cellulite_appearance', 'Cellulite Appearance', 'Dry brushing may temporarily improve circulation and skin texture, giving a smoother short-term appearance.', 'Use a dry brush in upward strokes toward the heart before showering, a few times weekly.', '2-3x weekly.', 'Note texture immediately after and over weeks.', 'Improved surface circulation is commonly cited for dry brushing''s temporary smoothing effect.', NULL, true),
('hydration_cellulite', 'Stay Hydrated and Reduce Excess Sodium', 'cellulite_appearance', 'Cellulite Appearance', 'Good hydration and lower sodium intake can reduce fluid retention that sometimes emphasizes cellulite appearance.', 'Drink water consistently through the day and moderate very salty foods.', 'Daily.', 'Track water intake and appearance over a month.', 'Fluid retention can affect how pronounced cellulite appears.', NULL, true),
('elevate_legs_varicose', 'Elevate Your Legs Daily', 'varicose_veins', 'Varicose & Spider Veins', 'Elevating legs above heart level helps blood flow back up from the legs, reducing pressure on vein walls.', 'Lie down and prop your legs up on a pillow or wall for 15-20 minutes daily.', 'Daily.', 'Note leg heaviness before/after.', 'Leg elevation is a standard, well-supported measure for venous pressure relief.', NULL, false),
('compression_varicose', 'Compression Stockings', 'varicose_veins', 'Varicose & Spider Veins', 'Gentle, graduated compression supports vein walls and improves blood flow back to the heart.', 'Wear compression stockings, especially during long periods of standing or sitting.', 'During the day, especially long standing/sitting.', 'Track leg comfort over 2-3 weeks.', 'Compression therapy is a well-established, evidence-backed approach for varicose vein symptoms.', NULL, true),
('move_regularly_varicose', 'Move Regularly, Avoid Prolonged Standing/Sitting', 'varicose_veins', 'Varicose & Spider Veins', 'Muscle contractions from movement act as a pump helping blood return from the legs.', 'Take a short walk or do calf raises every 30-45 minutes if you stand or sit for long periods.', 'Every 30-45 minutes during long stretches.', 'Log activity breaks and leg comfort.', 'Regular movement supports venous return and reduces vein pressure.', 'Sudden leg swelling, redness, or pain in one leg needs urgent medical attention.', true),
('elevate_feet_swelling', 'Elevate Feet Above Heart Level', 'swollen_ankles_feet', 'Swollen Ankles & Feet', 'Elevation uses gravity to help fluid drain from the lower legs back into circulation.', 'Lie down and rest your feet on a pillow or raised surface for 15-20 minutes.', 'As needed, evenings especially.', 'Note swelling before/after.', 'Elevation is a standard first-line measure for dependent swelling.', NULL, false),
('reduce_salt_swelling', 'Reduce Salt Intake', 'swollen_ankles_feet', 'Swollen Ankles & Feet', 'Excess sodium causes the body to retain more fluid, which commonly settles in the lower legs and feet.', 'Cut back on processed and salty foods, especially in the days before your period.', 'Ongoing, especially pre-period.', 'Track salt intake alongside swelling.', 'Sodium intake is directly linked to fluid retention and swelling.', NULL, true),
('ankle_movement_swelling', 'Move Your Ankles Regularly', 'swollen_ankles_feet', 'Swollen Ankles & Feet', 'Ankle movement activates the calf muscle pump that helps push fluid back up the legs.', 'Rotate your ankles and flex your feet for a minute every hour if sitting for long periods.', 'Hourly during long sitting.', 'Track swelling over the day.', 'Muscle pump activation is a well-known mechanism for reducing dependent edema.', 'Sudden swelling in one leg only, especially with pain, needs urgent medical review.', true),
('exfoliate_kp', 'Gentle Exfoliation', 'keratosis_pilaris', 'Bumpy "Chicken Skin" (Keratosis Pilaris)', 'Regularly removing the buildup of dead skin cells around hair follicles reduces the bumpy texture.', 'Use a soft washcloth or gentle exfoliating scrub on affected areas 2-3 times weekly.', '2-3x weekly.', 'Photograph monthly.', 'Regular gentle exfoliation is a standard recommendation for keratosis pilaris.', 'Avoid harsh scrubbing, which can worsen irritation.', false),
('urea_cream_kp', 'Daily Moisturizing with Urea or Lactic Acid Cream', 'keratosis_pilaris', 'Bumpy "Chicken Skin" (Keratosis Pilaris)', 'These ingredients help soften and smooth the rough, bumpy texture over consistent use.', 'Apply a cream containing urea or lactic acid to affected areas daily after showering.', 'Daily.', 'Track texture monthly.', 'Urea and lactic acid are well-documented keratolytic ingredients used for this exact condition.', NULL, true),
('lukewarm_showers_kp', 'Lukewarm Showers, Not Hot', 'keratosis_pilaris', 'Bumpy "Chicken Skin" (Keratosis Pilaris)', 'Hot water strips natural oils and can worsen the dryness that makes keratosis pilaris more noticeable.', 'Shower with lukewarm rather than hot water, and moisturize immediately after.', 'Every shower.', 'Note skin texture over a few weeks.', 'Hot water is known to worsen skin dryness and irritation.', NULL, true),
('saltwater_ulcers', 'Saltwater Rinse', 'mouth_ulcers', 'Mouth Ulcers / Canker Sores', 'A saline rinse helps clean the area and may reduce inflammation around the ulcer.', 'Dissolve half a teaspoon of salt in warm water and rinse your mouth gently, several times daily.', '2-3x daily until healed.', 'Track healing time.', 'Saltwater rinses are a widely recommended home remedy for oral ulcers.', NULL, false),
('avoid_acidic_ulcers', 'Avoid Acidic and Spicy Foods', 'mouth_ulcers', 'Mouth Ulcers / Canker Sores', 'These foods can irritate an open ulcer and slow healing.', 'Avoid citrus, tomatoes, and spicy foods until the ulcer heals.', 'Until healed.', 'Note pain levels with different foods.', 'Acidic and spicy foods are known irritants to open oral lesions.', NULL, true),
('honey_ulcers', 'Honey Application', 'mouth_ulcers', 'Mouth Ulcers / Canker Sores', 'Honey has natural antibacterial properties and may support faster healing of oral ulcers.', 'Dab a small amount of raw honey directly on the ulcer a few times daily.', '2-3x daily.', 'Track size and pain over a few days.', 'Honey has documented wound-healing and antibacterial properties, including for oral ulcers.', 'Ulcers lasting more than 2 weeks, or very large/painful ones, should be checked by a doctor.', true),
('ice_early_cold_sore', 'Apply Ice at the First Tingle', 'cold_sores', 'Cold Sores', 'Cold sores often start with a tingling sensation, and early cooling may reduce severity.', 'Apply an ice cube wrapped in cloth to the area as soon as you feel tingling, for a few minutes.', 'At first sign of tingling.', 'Note whether early icing reduces severity/duration.', 'Early intervention is commonly recommended to reduce cold sore severity.', NULL, false),
('hygiene_cold_sore', 'Keep the Area Clean and Avoid Touching', 'cold_sores', 'Cold Sores', 'Cold sores are contagious, and touching or picking can spread the virus or worsen the sore.', 'Wash hands before and after touching the area, and avoid picking at the sore.', 'Throughout the outbreak.', 'Track healing time.', 'Hygiene measures reduce spread and secondary infection risk.', 'Avoid kissing or sharing utensils during an active outbreak.', true),
('triggers_cold_sore', 'Manage Your Triggers', 'cold_sores', 'Cold Sores', 'Stress, sun exposure, and fatigue are common triggers for cold sore outbreaks.', 'Note what preceded your last few outbreaks and manage those triggers (rest, sun protection, stress management).', 'Ongoing.', 'Log outbreaks alongside possible triggers.', 'Known triggers for herpes simplex reactivation include stress, illness, and UV exposure.', 'Frequent or severe outbreaks are worth discussing with a doctor for antiviral options.', true),
('soft_brush_gums', 'Switch to a Soft-Bristled Toothbrush', 'bleeding_gums', 'Bleeding, Sensitive Gums', 'Hard bristles can injure sensitive gum tissue, especially when gums are already inflamed.', 'Use a soft-bristled toothbrush and brush gently in circular motions.', 'Every brushing.', 'Track bleeding over 2 weeks.', 'Soft-bristled brushes are universally recommended for sensitive or bleeding gums.', NULL, false),
('saltwater_gums', 'Saltwater Rinse', 'bleeding_gums', 'Bleeding, Sensitive Gums', 'Saline rinses can reduce inflammation and bacteria that contribute to gum bleeding.', 'Rinse with warm salt water after brushing, twice daily.', 'Twice daily.', 'Track gum bleeding and swelling.', 'Saltwater rinses reduce oral bacteria and mild inflammation.', NULL, true),
('flossing_gums', 'Do Not Skip Flossing (Gently)', 'bleeding_gums', 'Bleeding, Sensitive Gums', 'Plaque buildup between teeth is a major cause of gum inflammation and bleeding; gentle regular flossing removes it.', 'Floss gently once daily, being careful not to snap the floss into the gum line.', 'Daily.', 'Track bleeding over 2-3 weeks of consistent flossing.', 'Regular flossing is a first-line recommendation for gum health.', 'Bleeding gums that don''t improve after 2 weeks of good hygiene need a dentist visit.', true),
('desensitizing_toothpaste', 'Use a Toothpaste for Sensitive Teeth', 'sensitive_teeth', 'Sensitive Teeth', 'These toothpastes contain compounds that block the tiny channels in teeth that transmit pain sensations.', 'Switch to a desensitizing toothpaste and use it consistently for at least 2 weeks.', 'Every brushing, ongoing.', 'Rate sensitivity to hot/cold weekly.', 'Potassium nitrate and similar compounds are well-documented for reducing tooth sensitivity.', NULL, false),
('avoid_extremes_teeth', 'Avoid Very Hot or Cold Foods/Drinks Temporarily', 'sensitive_teeth', 'Sensitive Teeth', 'Extreme temperatures can trigger sharp pain in sensitive teeth while you work on the underlying cause.', 'Moderate very hot or cold foods and drinks until sensitivity improves.', 'Until improved.', 'Note trigger foods and pain levels.', 'Temperature extremes are the most common trigger for dentin sensitivity.', NULL, true),
('brushing_technique_teeth', 'Check Your Brushing Technique', 'sensitive_teeth', 'Sensitive Teeth', 'Brushing too hard can wear away enamel and expose sensitive areas of the tooth.', 'Use gentle, circular brushing motions rather than hard back-and-forth scrubbing.', 'Every brushing.', 'Track sensitivity over a month.', 'Aggressive brushing is a well-known contributor to enamel wear and sensitivity.', 'Persistent or worsening sensitivity should be checked by a dentist to rule out other causes.', true),
('twenty_rule_dry_eyes', 'Follow the 20-20-20 Rule', 'dry_eyes', 'Dry, Tired Eyes', 'Regular breaks from screens reduce the strain that contributes to dryness and eye fatigue.', 'Every 20 minutes, look at something 20 feet away for 20 seconds.', 'Throughout screen time.', 'Track eye comfort by end of day.', 'This rule is a widely recommended standard for reducing digital eye strain.', NULL, false),
('blink_dry_eyes', 'Blink More Often, Consciously', 'dry_eyes', 'Dry, Tired Eyes', 'Screen use reduces natural blink rate, which allows the eye surface to dry out faster.', 'Consciously blink fully and slowly every so often while working at a screen.', 'While using screens.', 'Note dryness levels.', 'Reduced blink rate during screen use is a documented cause of eye dryness.', NULL, true),
('humidifier_dry_eyes', 'Use a Humidifier or Warm Compress', 'dry_eyes', 'Dry, Tired Eyes', 'Dry air worsens eye dryness, and warm compresses can help stimulate natural oil production in the eyelids.', 'Use a humidifier in dry environments, or apply a warm compress to closed eyes for 5-10 minutes.', 'As needed.', 'Track comfort levels.', 'Warm compresses support the meibomian glands that keep eyes lubricated.', 'Persistent dryness or grittiness should be checked by an eye doctor.', true),
('screen_setup_eye_strain', 'Adjust Screen Brightness and Distance', 'eye_strain', 'Eye Strain (Screen Fatigue)', 'Screens that are too bright or too close force your eyes to work harder, leading to fatigue.', 'Match screen brightness to your surroundings and keep screens at least an arms length away.', 'Ongoing.', 'Track eye fatigue by end of day.', 'Screen ergonomics are a first-line recommendation for reducing digital eye strain.', NULL, false),
('breaks_eye_strain', 'Take Regular Screen Breaks', 'eye_strain', 'Eye Strain (Screen Fatigue)', 'Continuous close-up focus tires the eye muscles; regular breaks let them relax.', 'Step away from screens for 5 minutes every hour.', 'Hourly.', 'Log breaks and fatigue levels.', 'Regular breaks are consistently recommended to reduce eye strain.', NULL, true),
('lighting_eye_strain', 'Check Your Lighting Setup', 'eye_strain', 'Eye Strain (Screen Fatigue)', 'Glare and poor lighting force your eyes to strain more than necessary.', 'Reduce glare on screens and ensure your workspace has adequate, even lighting.', 'Ongoing.', 'Note fatigue after adjusting.', 'Poor lighting and glare are well-documented contributors to eye strain.', NULL, true),
('warm_compress_stye', 'Warm Compress', 'styes', 'Eyelid Styes', 'Heat helps the blocked gland causing the stye drain naturally and speeds healing.', 'Apply a warm, clean compress to the closed eyelid for 10-15 minutes, several times daily.', '3-4x daily until it resolves.', 'Track size and pain daily.', 'Warm compresses are the standard first-line treatment for styes.', NULL, false),
('hygiene_stye', 'Keep the Area Clean, Don''t Pop It', 'styes', 'Eyelid Styes', 'Squeezing a stye can spread infection; gentle cleaning supports healing instead.', 'Gently clean the eyelid with a clean cloth and avoid squeezing or popping the stye.', 'Daily.', 'Track healing progress.', 'Avoiding manipulation of the stye is standard medical advice to prevent spreading infection.', NULL, true),
('avoid_makeup_stye', 'Avoid Eye Makeup and Contacts Until Healed', 'styes', 'Eyelid Styes', 'Makeup and contact lenses can introduce more bacteria or irritate the healing area.', 'Skip eye makeup and contact lens wear until the stye fully resolves.', 'Until healed.', 'Track healing time.', 'Reducing contamination risk supports faster healing.', 'A stye that doesn''t improve in a week, or affects vision, needs a doctor.', true),
('saline_rinse_allergies', 'Rinse Your Sinuses', 'seasonal_allergies', 'Seasonal Allergies / Hay Fever', 'A saline rinse physically flushes out pollen and irritants from the nasal passages.', 'Use a saline nasal rinse or neti pot once daily during high-pollen periods.', 'Daily during flare season.', 'Track congestion and sneezing.', 'Nasal saline irrigation is a well-supported first-line measure for allergy symptoms.', 'Use distilled or previously boiled water, never straight tap water, for nasal rinses.', false),
('shower_bed_allergies', 'Shower Before Bed During High-Pollen Days', 'seasonal_allergies', 'Seasonal Allergies / Hay Fever', 'Pollen collects on skin and hair through the day; washing it off before bed reduces overnight exposure.', 'Shower and change clothes before bed on high-pollen days.', 'Evenings during flare season.', 'Track morning symptoms.', 'Reducing allergen exposure at night improves sleep and symptom control.', NULL, true),
('windows_allergies', 'Keep Windows Closed on High-Pollen Days', 'seasonal_allergies', 'Seasonal Allergies / Hay Fever', 'Limiting how much outdoor allergen gets into your home reduces overall exposure.', 'Check pollen forecasts and keep windows closed on high-count days, using a fan or AC instead.', 'As needed, seasonal.', 'Track symptoms against pollen forecasts.', 'Environmental control is a standard allergy management recommendation.', NULL, true),
('sleep_immunity', 'Prioritize Sleep, Especially Pre-Period', 'frequent_colds', 'Frequent Colds / Weak Immunity Around Period', 'Immune function dips somewhat with poor sleep, and hormonal shifts before your period can compound this.', 'Aim for consistent, adequate sleep, especially in the week before your period.', 'Ongoing, especially pre-period.', 'Log sleep and illness frequency alongside cycle phase.', 'Sleep is well documented to directly affect immune function.', NULL, false),
('vitc_zinc_immunity', 'Vitamin C and Zinc-Rich Foods', 'frequent_colds', 'Frequent Colds / Weak Immunity Around Period', 'These nutrients support normal immune function and are found in many everyday foods.', 'Include citrus fruits, peppers, and seeds/nuts regularly in your diet.', 'Ongoing, dietary.', 'Track cold frequency over a few months.', 'Vitamin C and zinc have documented roles in immune function.', NULL, true),
('stress_immunity', 'Manage Stress Levels', 'frequent_colds', 'Frequent Colds / Weak Immunity Around Period', 'Chronic stress suppresses immune response, making you more susceptible to catching colds.', 'Build in a daily stress-reducing habit, even just 5-10 minutes of quiet time or movement.', 'Daily.', 'Track stress and illness frequency together.', 'Chronic stress is well documented to weaken immune defenses.', NULL, true),
('rest_shin_splints', 'Rest and Reduce High-Impact Activity', 'shin_splints', 'Shin Splints', 'Shin splints result from repeated stress on the shin bone and muscles; reducing impact allows healing.', 'Cut back on running or jumping activities until pain subsides, substituting swimming or cycling.', 'Until pain resolves.', 'Rate pain daily.', 'Activity modification is the standard first step in shin splint recovery.', NULL, false),
('ice_shin_splints', 'Ice the Area After Activity', 'shin_splints', 'Shin Splints', 'Cold reduces inflammation in the shin muscles and connective tissue after exertion.', 'Apply an ice pack wrapped in a cloth to the shins for 15-20 minutes after activity.', 'After activity, as needed.', 'Track pain before/after icing.', 'Cold therapy is a standard approach for exercise-related inflammation.', 'Never apply ice directly to skin.', true),
('footwear_shin_splints', 'Check Your Footwear', 'shin_splints', 'Shin Splints', 'Worn-out or unsupportive shoes are a common, fixable contributor to shin splints.', 'Replace worn running shoes and consider ones with better shock absorption for your activity.', 'Before returning to activity.', 'Track pain after switching footwear.', 'Proper footwear is a well-established factor in preventing shin splints.', 'Persistent or worsening pain needs medical evaluation to rule out a stress fracture.', true),
('morning_stretch_plantar', 'Morning Calf and Foot Stretches', 'plantar_pain', 'Foot Arch Pain (Plantar Fasciitis-Type)', 'Arch tissue tightens overnight; gentle stretching before standing reduces that first-step pain.', 'Before getting out of bed, gently stretch your foot by pulling your toes back toward your shin for 30 seconds.', 'Every morning.', 'Rate morning pain daily.', 'Stretching the plantar fascia is a first-line, well-supported treatment approach.', NULL, false),
('bottle_roll_plantar', 'Roll Your Foot Over a Cold Bottle', 'plantar_pain', 'Foot Arch Pain (Plantar Fasciitis-Type)', 'This combines gentle massage with cold therapy to ease inflammation along the arch.', 'Roll your bare foot back and forth over a frozen water bottle for 5-10 minutes.', '1-2x daily.', 'Track pain before/after.', 'This combination technique is commonly recommended for plantar fasciitis relief.', NULL, true),
('footwear_plantar', 'Choose Supportive Footwear', 'plantar_pain', 'Foot Arch Pain (Plantar Fasciitis-Type)', 'Flat or unsupportive shoes put extra strain on the arch; proper support redistributes that load.', 'Wear shoes with good arch support, and consider an insole if your regular shoes lack it.', 'Ongoing.', 'Track pain across different footwear.', 'Arch support is a standard recommendation for managing plantar fasciitis.', 'Persistent heel/arch pain lasting more than a few weeks should be seen by a doctor.', true),
('moisturize_mouth_corners', 'Keep the Area Moisturized', 'cracked_mouth_corners', 'Cracked Corners of the Mouth', 'Cracked mouth corners often result from dryness and repeated licking, and consistent moisture supports healing.', 'Apply a thick lip balm or petroleum jelly to the corners of your mouth several times daily.', 'Several times daily until healed.', 'Track healing over a week.', 'Occlusive moisturizers are the standard first approach for angular cheilitis-type cracking.', NULL, false),
('avoid_licking_mouth_corners', 'Avoid Licking the Area', 'cracked_mouth_corners', 'Cracked Corners of the Mouth', 'Saliva can worsen irritation and slow healing of already-cracked skin.', 'Consciously avoid licking the corners of your mouth, even though it may feel soothing momentarily.', 'Ongoing until healed.', 'Note improvement over several days.', 'Saliva-related irritation is a recognized factor that delays healing in this area.', NULL, true),
('nutrition_mouth_corners', 'Check for Nutritional Gaps', 'cracked_mouth_corners', 'Cracked Corners of the Mouth', 'Recurring cracking has been linked to low iron, B vitamins, or zinc in some cases.', 'Ensure a varied diet with iron and B-vitamin-rich foods (leafy greens, eggs, beans).', 'Ongoing, dietary.', 'Track recurrence over a couple of months.', 'Nutritional deficiencies are a recognized contributing factor in recurrent angular cheilitis.', 'If it persists despite care, or looks infected, see a doctor - it can sometimes need an antifungal or antibiotic cream.', true),
('stretch_restless_arms', 'Gentle Arm Stretches Before Bed', 'restless_arms', 'Restless Arms', 'Similar to restless legs, restless arms may ease with gentle stretching that releases muscular tension.', 'Stretch your arms and shoulders gently for a few minutes before bed.', 'Nightly.', 'Rate arm restlessness before sleep.', 'Stretching is a commonly recommended approach for restless limb sensations.', NULL, false),
('iron_restless_arms', 'Check Iron Levels', 'restless_arms', 'Restless Arms', 'Restless limb sensations, including in the arms, have been linked to low iron in some cases, similar to restless legs.', 'Include iron-rich foods in your diet and consider asking a doctor about testing if it is frequent.', 'Ongoing, dietary.', 'Track frequency alongside diet.', 'Iron deficiency is a recognized contributing factor in restless limb syndromes.', NULL, true),
('caffeine_restless_arms', 'Reduce Evening Caffeine', 'restless_arms', 'Restless Arms', 'Stimulants can heighten nervous system activity, making restless sensations more noticeable at night.', 'Avoid caffeine in the afternoon and evening.', 'Afternoon/evening.', 'Track restlessness on days with/without evening caffeine.', 'Caffeine is a known trigger for restless limb sensations.', NULL, true),
('caffeine_rest_eye_twitch', 'Reduce Caffeine and Get More Rest', 'eye_twitching', 'Eye Twitching', 'Eye twitching (myokymia) is commonly linked to fatigue, stress, and excess caffeine.', 'Cut back on caffeine and prioritize consistent, adequate sleep for a few days.', 'Ongoing.', 'Track twitching frequency alongside sleep and caffeine.', 'Fatigue and caffeine are the most commonly cited triggers for eyelid twitching.', NULL, false),
('screen_time_eye_twitch', 'Reduce Screen Time and Eye Strain', 'eye_twitching', 'Eye Twitching', 'Prolonged screen focus can tire the small eyelid muscles, contributing to twitching.', 'Take regular breaks from screens and rest your eyes for a few minutes each hour.', 'Hourly during screen use.', 'Track twitching alongside screen time.', 'Eye strain is a recognized contributor to eyelid twitching.', NULL, true),
('warm_compress_eye_twitch', 'Warm Compress on the Eyelid', 'eye_twitching', 'Eye Twitching', 'Gentle warmth can relax the small muscles around the eye that are prone to spasming.', 'Apply a warm compress to the affected eyelid for 5-10 minutes.', 'As needed.', 'Track twitch frequency and duration.', 'Warm compresses are commonly used to relax muscle spasms.', 'Twitching lasting more than a few weeks, or affecting other parts of the face, should be checked by a doctor.', true),
('reach_out_loneliness', 'Reach Out to One Person Today', 'loneliness', 'Feelings of Loneliness', 'Even brief, low-pressure contact with someone you trust can meaningfully ease the feeling of isolation.', 'Send a message or make a short call to one person you feel comfortable with today.', 'Daily, or whenever loneliness feels heavy.', 'Note how you feel before and after connecting.', 'Social contact, even brief, is well documented to reduce feelings of loneliness.', NULL, false),
('group_activity_loneliness', 'Join a Low-Pressure Group Activity', 'loneliness', 'Feelings of Loneliness', 'Shared activities create natural, lower-pressure opportunities for connection compared to one-on-one plans.', 'Look for a class, group walk, or community activity you could join, even just to observe at first.', 'Weekly, ongoing.', 'Note mood after attending.', 'Group activities are associated with reduced loneliness in research on social wellbeing.', NULL, true),
('honesty_loneliness', 'Be Honest About How You''re Feeling With Someone You Trust', 'loneliness', 'Feelings of Loneliness', 'Naming the feeling to someone else can reduce its intensity and open the door to real support.', 'Tell one trusted person that you''ve been feeling lonely lately, without needing to explain everything.', 'When you feel ready.', 'Note how it felt to share.', 'Disclosure to trusted others is linked to reduced emotional burden in psychological research.', 'If loneliness feels constant and overwhelming, talking to a counselor or therapist can help.', true),
('remove_one_thing_burnout', 'Identify One Thing to Remove from Your Plate', 'burnout', 'Burnout & Chronic Overwhelm', 'Burnout often comes from sustained overload; removing even one obligation can create real relief.', 'Look at your commitments this week and identify one thing you can delay, delegate, or drop.', 'Weekly review.', 'Note energy levels after reducing load.', 'Reducing workload is a first-line recommendation in burnout recovery approaches.', NULL, false),
('schedule_rest_burnout', 'Schedule Real Rest, Not Just Less Work', 'burnout', 'Burnout & Chronic Overwhelm', 'Burnout recovery needs genuine restorative rest, not just a lighter to-do list.', 'Block out time for something restorative - not productive - like a walk, nap, or quiet time, at least once today.', 'Daily.', 'Track rest quality alongside energy levels.', 'Active recovery and rest are distinct from simply reducing workload in burnout research.', NULL, true),
('warning_signs_burnout', 'Notice the Warning Signs Early', 'burnout', 'Burnout & Chronic Overwhelm', 'Recognizing your personal burnout signals (irritability, exhaustion, cynicism) lets you intervene before it deepens.', 'Reflect on what your early burnout signs tend to be, and check in with yourself for them weekly.', 'Weekly.', 'Log energy, mood, and motivation weekly.', 'Early recognition of burnout symptoms is associated with better recovery outcomes.', 'Persistent burnout that does not improve with rest may benefit from talking to a therapist or doctor.', true);
